package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.nio.file.*;
final class MeetingConsent {
 static String fingerprint(File f,JSONObject m)throws Exception{StringBuilder value=new StringBuilder(m.toString());int count=m.getJSONArray("parts").length();for(int first=0;first<count;first+=6){File cached=new File(f,String.format(java.util.Locale.US,"transcript-%04d.gcm",first));value.append(':').append(cached.length()).append(':').append(cached.lastModified());}return RecorderPhotoStore.hash(value.toString().getBytes("UTF-8"));}
 static synchronized JSONObject preview(Context c,String id)throws Exception{File f=MeetingAudioStore.folder(c,id);JSONObject m=MeetingAudioStore.meta(f);JSONArray parts=m.getJSONArray("parts");long bytes=0;int requests=1;for(int first=0;first<parts.length();first+=6)if(!new File(f,String.format(java.util.Locale.US,"transcript-%04d.gcm",first)).isFile()){requests++;for(int i=first;i<Math.min(parts.length(),first+6);i++)bytes+=parts.getJSONObject(i).getLong("bytes");}for(int first=0;first<parts.length();first+=6){File cache=new File(f,String.format(java.util.Locale.US,"transcript-%04d.gcm",first));if(cache.isFile()){if(cache.length()>2500000)throw new IOException("保存済み文字起こしが大きすぎます");try{DeviceSecrets.photos().decrypt(Files.readAllBytes(cache.toPath()));}catch(Exception corrupt){throw new IOException("保存済み文字起こしを検証できません。元データは保持しています");}}}String token=java.util.UUID.randomUUID().toString();JSONObject ticket=new JSONObject().put("id",id).put("token",token).put("fingerprint",fingerprint(f,m)).put("expiresAt",System.currentTimeMillis()+300000).put("audioBytes",bytes).put("audioMs",bytes/32).put("maximumRequests",requests);JSONObject store=ReviewStore.read(c,"meeting-consents");JSONArray old=store.optJSONArray("items"),all=new JSONArray();if(old!=null)for(int i=0;i<old.length();i++)if(old.getJSONObject(i).optLong("expiresAt")>System.currentTimeMillis()&&all.length()<11)all.put(old.get(i));all.put(ticket);ReviewStore.write(c,"meeting-consents",new JSONObject().put("items",all));return new JSONObject(ticket.toString()).put("provider","Gemini").put("message","未処理の録音区間と会議の文字起こし・要約用テキストをGeminiへ送ります。会話・氏名などの個人情報を含む場合があります。料金が発生する可能性があります。音声量は未処理分、文字起こしは会議全体が要約対象です。中止しても送信済み分や料金は取り消せません。");}
 static synchronized void consume(Context c,String id,String token)throws Exception{ReviewStore.validId(token);JSONObject store=ReviewStore.read(c,"meeting-consents");JSONArray all=store.optJSONArray("items");if(all==null)throw new IOException("送信範囲を先に確認してください");for(int i=0;i<all.length();i++){JSONObject ticket=all.getJSONObject(i);if(token.equals(ticket.optString("token"))&&id.equals(ticket.optString("id"))){if(ticket.optBoolean("used")||ticket.optLong("expiresAt")<System.currentTimeMillis()||!ticket.getString("fingerprint").equals(fingerprint(MeetingAudioStore.folder(c,id),MeetingAudioStore.meta(MeetingAudioStore.folder(c,id)))))throw new IOException("確認が失効・更新されています。送信範囲を開き直してください");ticket.put("used",true);ReviewStore.write(c,"meeting-consents",store);return;}}throw new IOException("送信範囲を先に確認してください");}
 private MeetingConsent(){}
}
